
"""Audit feedback generated by the real resume analysis pipeline.

This is an LLM-judge audit, not an accuracy benchmark:
generated items do not have human-verified reference labels.
"""

import asyncio
import json
import logging
import sys
from collections import Counter
from datetime import datetime, timezone
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from app.integrations.llm.base import LLMError
from app.modules.resume.feedback_quality_judge import FeedbackQualityJudge
from app.modules.resume.schemas import ResumeAnalysisRequest
from app.modules.resume.service import ResumeAnalysisService

BASE_DIR = Path(__file__).resolve().parent.parent
FIXTURE_DIR = BASE_DIR / "tests" / "fixtures"
OUTPUT_DIR = BASE_DIR / "eval_results"

DIMENSIONS = ("grounded", "relevant", "actionable")
SECTIONS = (
    "strengths",
    "improvement_suggestions",
    "likely_interview_questions",
)

logger = logging.getLogger(__name__)


async def run_evaluation():
    pdf_path = FIXTURE_DIR / "sample_resume.pdf"
    resume_text_path = FIXTURE_DIR / "sample_resume.txt"
    job_path = FIXTURE_DIR / "sample_job_description.txt"

    for path in (pdf_path, resume_text_path, job_path):
        if not path.exists():
            raise FileNotFoundError(
                f"Required evaluation fixture not found: {path}. "
                "Check the fixture files and generate the PDF if necessary."
            )

    request = ResumeAnalysisRequest(
        job_role="Junior Machine Learning Engineer",
        job_description=job_path.read_text(encoding="utf-8"),
    )

    # Run the production analysis pipeline, including PDF parsing and LLM feedback.
    service = ResumeAnalysisService()
    analysis = await service.analyze(pdf_path.read_bytes(), request)

    # This is the source fixture text used to create the synthetic PDF.
    # It provides the judge with the candidate evidence for this audit.
    resume_text = resume_text_path.read_text(encoding="utf-8")

    judge = FeedbackQualityJudge()
    results = []

    feedback_items = [
        (section, item)
        for section in SECTIONS
        for item in getattr(analysis, section)
    ]

    if not feedback_items:
        raise ValueError("The analyzer returned no feedback items to evaluate.")

    for index, (section, item) in enumerate(feedback_items, start=1):
        print(f"[{index}/{len(feedback_items)}] {section}: {item[:90]}")

        case = {
            "resume_text": resume_text,
            "job_role": analysis.job_role,
            "section": section,
            "feedback_item": item,
        }

        try:
            prediction = await judge.evaluate(case)
        except (LLMError, ValueError) as exc:
            logger.exception("Judge failed on generated item %s", index)
            raise RuntimeError(
                f"Could not evaluate generated feedback item {index}: {exc}"
            ) from exc

        results.append({
            "item_id": f"generated_{index:03d}",
            **case,
            "judge": prediction,
        })

    label_counts = {
        dimension: {
            "true": sum(
                row["judge"][dimension] is True for row in results
            ),
            "false": sum(
                row["judge"][dimension] is False for row in results
            ),
        }
        for dimension in DIMENSIONS
    }

    section_counts = Counter(row["section"] for row in results)

    # Grounding and relevance concerns warrant review.
    # Actionability is reported but is not treated as a universal pass/fail:
    # a strength can be useful without prescribing a next step.
    review_items = [
        {
            "item_id": row["item_id"],
            "section": row["section"],
            "feedback_item": row["feedback_item"],
            "concerns": [
                dimension
                for dimension in ("grounded", "relevant")
                if row["judge"][dimension] is False
            ],
            "reasoning": row["judge"]["reasoning"],
        }
        for row in results
        if any(
            row["judge"][dimension] is False
            for dimension in ("grounded", "relevant")
        )
    ]

    report = {
        "evaluation_type": "generated_resume_feedback_quality_audit",
        "method": "production_analyzer_plus_llm_judge",
        "completed_at_utc": datetime.now(timezone.utc).isoformat(),
        "job_role": analysis.job_role,
        "feedback_item_count": len(results),
        "section_counts": dict(section_counts),
        "judge_label_counts": label_counts,
        "items_requiring_review": len(review_items),
        "review_items": review_items,
        "warning": (
            "Judge labels are automated assessments, not human-verified "
            "ground truth. These counts are not accuracy, precision, recall, "
            "or proof of objective feedback quality. Review flagged items "
            "manually and investigate possible judge false positives."
        ),
        "analysis": analysis.model_dump(),
        "results": results,
    }

    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    output_path = OUTPUT_DIR / "generated_resume_feedback_audit.json"
    output_path.write_text(
        json.dumps(report, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )

    print("\nJudge label counts:")
    print(json.dumps(label_counts, indent=2))
    print(f"\nItems requiring review: {len(review_items)}")
    print(f"Report saved to: {output_path}")


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    asyncio.run(run_evaluation())
